for number in range(9, 16):      # FOR Number ← 9 TO 15 (range stops before 16)
    if number % 15 == 0:
        print("FizzBuzz")
    elif number % 3 == 0:        # elif = ELSE followed by a nested IF
        print("Fizz")
    elif number % 5 == 0:
        print("Buzz")
    else:
        print(number)

# Python has no REPEAT ... UNTIL; this is the usual equivalent
codes = iter(["12", "12345", "7a9b"])   # stands in for input()
while True:
    code = next(codes)
    if len(code) == 4:                 # UNTIL LENGTH(Code) = 4
        break
print("Code accepted:", code)
